@Controller('health')
export class HealthController {
  constructor(
    private health: HealthCheckService,
    private db: TypeOrmHealthIndicator,
    private memory: MemoryHealthIndicator,
  ) {}

  // BUG: one endpoint used for BOTH liveness and readiness, and it pings the DB.
  // A DB outage will fail liveness -> kubelet restarts every pod -> restart storm.
  @Get()
  @HealthCheck()
  check() {
    return this.health.check([
      () => this.db.pingCheck('database'),
    ]);
  }
}

// livenessProbe:  httpGet: { path: /health, port: 3000 }
// readinessProbe: httpGet: { path: /health, port: 3000 }

