@Controller('health')
export class HealthController {
  constructor(
    private health: HealthCheckService,
    private db: TypeOrmHealthIndicator,
    private memory: MemoryHealthIndicator,
  ) {}

  @Get('live')        // dependency-free: only the process's own health
  @HealthCheck()
  liveness() {
    return this.health.check([
      () => this.memory.checkHeap('memory_heap', 512 * 1024 * 1024),
    ]);
  }

  @Get('ready')       // deps allowed: gates the load balancer
  @HealthCheck()
  readiness() {
    return this.health.check([
      () => this.db.pingCheck('database'),
    ]);
  }
}

// livenessProbe:  httpGet: { path: /health/live,  port: 3000 }
// readinessProbe: httpGet: { path: /health/ready, port: 3000 }

Why: liveness now runs only a dependency-free indicator (heap/event-loop), so a DB outage can never restart the pod. The DB pingCheck moves to readiness, whose failure only drains the pod from the load balancer and leaves the process alive to recover. The probes point at the two separate paths. A transient DB blip now drains and self-heals instead of triggering a cluster-wide restart storm.

