@Controller('health')
export class HealthController {
  constructor(
    private health: HealthCheckService,
    private db: TypeOrmHealthIndicator,
    private memory: MemoryHealthIndicator,
  ) {}

  @Get('live')        // без зависимостей: только здоровье самого процесса
  @HealthCheck()
  liveness() {
    return this.health.check([
      () => this.memory.checkHeap('memory_heap', 512 * 1024 * 1024),
    ]);
  }

  @Get('ready')       // зависимости можно: гейтит load balancer
  @HealthCheck()
  readiness() {
    return this.health.check([
      () => this.db.pingCheck('database'),
    ]);
  }
}

// livenessProbe:  httpGet: { path: /health/live,  port: 3000 }
// readinessProbe: httpGet: { path: /health/ready, port: 3000 }

Почему: liveness теперь гоняет только индикатор без зависимостей (heap/event loop), так что сбой базы никогда не рестартит под. DB pingCheck переезжает в readiness, чей провал лишь сливает под из load balancer и оставляет процесс живым для восстановления. Пробы указывают на два раздельных пути. Транзиентный сбой базы теперь сливает и самоисцеляется вместо запуска кластерного шторма рестартов.
